def init():
    return dict(x1=0, x2=0, x3=0)

def step(state, inputs):
    outputs = dict()
    if inputs.get("rst", 0):
        state["x1"] = 0
        state["x2"] = 0
        state["x3"] = 0
        outputs["out_data"] = 0
    else:
        x = int(inputs.get("x", 0)) & 255
        if x >= 128:
            x = x - 256
        y = 3 * x - 5 * state["x1"] + 7 * state["x2"] - 2 * state["x3"]
        state["x3"] = state["x2"]
        state["x2"] = state["x1"]
        state["x1"] = x
        outputs["out_data"] = y & 8191
    return state, outputs
